t.script:
document.addEventListener('DOMContentLoaded', function () {
	const root = document.getElementById('muk_ai_browser_connect');
	const button = document.getElementById('muk_ai_browser_pair_btn');
	const status = document.getElementById('muk_ai_browser_status');
	if (!root || !button) {
		return;
	}
	button.addEventListener('click', async function () {
		status.textContent = 'Generating…';
		try {
			const response = await fetch('/muk_ai_browser/connect/begin', {
				method: 'POST',
				headers: { 'Content-Type': 'application/json' },
				body: JSON.stringify({
					jsonrpc: '2.0',
					method: 'call',
					params: { device_label: navigator.userAgent },
				}),
			});
			const data = await response.json();
			const result = (data && data.result) || {};
			const code = result.pairing_code;
			const extensionId = root.dataset.extensionId;
			if (code && extensionId && window.chrome && chrome.runtime) {
				chrome.runtime.sendMessage(extensionId, {
					type: 'pair',
					code: code,
				});
				status.textContent = 'Pairing code sent to the extension.';
			} else if (code) {
				status.textContent = 'Pairing code: ' + code;
			} else {
				status.textContent = 'Could not generate a pairing code.';
			}
		} catch (error) {
			status.textContent = 'Pairing failed: ' + error;
		}
	});
});
